const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let guest_id = null;
  try { guest_id = $('Has Min Signal').all()[i].json.id; } catch (e) {}
  if (!guest_id) { try { guest_id = $('Explode Guests').all()[i].json.id; } catch (e) {} }
  const content = item.json.content && item.json.content[0] && item.json.content[0].text;
  let parsed = { pitch_draft: null, suggested_angles: null, quality_score: 'red', quality_reason: 'no Sonnet response' };
  if (content) {
    try {
      const cleaned = content.replace(/```json\s*|\s*```/g, '').trim();
      parsed = JSON.parse(cleaned);
    } catch (e) {
      parsed = { pitch_draft: null, suggested_angles: null, quality_score: 'red', quality_reason: 'parse_error: ' + e.message };
    }
  }
  const EM = String.fromCharCode(0x2014);
  if (parsed.pitch_draft && parsed.pitch_draft.includes(EM)) {
    parsed.pitch_draft = parsed.pitch_draft.replace(/\u2014/g, ', ');
    parsed.quality_reason = (parsed.quality_reason || '') + ' (em-dashes scrubbed)';
  }
  if (parsed.suggested_angles && parsed.suggested_angles.includes(EM)) {
    parsed.suggested_angles = parsed.suggested_angles.replace(/\u2014/g, ', ');
  }
  out.push({ json: { guest_id, pitch_draft: parsed.pitch_draft, suggested_angles: parsed.suggested_angles, quality_score: parsed.quality_score, quality_reason: parsed.quality_reason } });
}
return out;
